/**
 * A choice sheet without a field; all open state belongs to the caller.
 * CHECKS.md §78 (provisional, agent): [errorKey] identifies each failed attempt, even with identical [error].
 * Keyboard focus moves to the error after scrolling; touch focus stays unchanged.
 */
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun <T> SbChoiceSheet(
    title: String,
    options: List<Pair<T, String>>,
    selected: T,
    onChange: (T) -> Unit,
    expanded: Boolean,
    onExpandedChange: (Boolean) -> Unit,
    meta: Map<T, String> = emptyMap(),
    disabledOptions: Set<T> = emptySet(),
    error: String? = null,
    extraAction: (@Composable () -> Unit)? = null,
    backdropColor: Color = SebaroTheme.colors.bg,
    errorDetails: (@Composable () -> Unit)? = null,
    closeOnChoice: Boolean = true,
    errorKey: Any? = error,
) {
    if (!expanded) return
    val first = options.indexOfFirst { it.first == selected && it.first !in disabledOptions }
        .takeIf { it >= 0 } ?: options.indexOfFirst { it.first !in disabledOptions }
    // Primitive keys stay saveable even when T itself is not Parcelable; retain identity if options reorder.
    val rowKeys = remember { mutableMapOf<T, String>() }
    val keys = options.map { (value, _) -> rowKeys.getOrPut(value) { "choice-row:${rowKeys.size}" } }
    val focus = remember { FocusRequester() }
    val errorFocus = remember { FocusRequester() }
    val errorInteraction = remember { MutableInteractionSource() }
    val firstEnabledFocus = remember { FocusRequester() }
    val errorScope = rememberCoroutineScope()
    val firstEnabled = options.indexOfFirst { it.first !in disabledOptions }
    var requestedFocus by remember { mutableStateOf(false) }
    val scroll = rememberLazyListState(initialFirstVisibleItemIndex = if (error != null) 0 else first.coerceAtLeast(0))
    SbBottomSheet(onDismissRequest = { onExpandedChange(false) }, title = title,
        sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true), backdropColor = backdropColor) {
        val input = LocalInputModeManager.current
        val focusManager = LocalFocusManager.current
        // CHECKS.md §78 (provisional, agent): each failed attempt scrolls and gets one fresh polite region.
        LaunchedEffect(errorKey, error != null) {
            if (error != null) {
                scroll.scrollToItem(0)
                snapshotFlow { scroll.layoutInfo.visibleItemsInfo.any { it.key == "choice-error" } }.sbFirstVisible { it }
                withFrameNanos { }
                if (input.inputMode == InputMode.Keyboard) errorFocus.requestFocus()
            }
        }
        LazyColumn(Modifier.fillMaxWidth().selectableGroup(), state = scroll) {
            if (error != null) item(key = "choice-error") {
                // CHECKS.md §79 (provisional, agent): the list clips, so the focus ring's room above the first item
                Column(Modifier.padding(start = SebaroTheme.tokens.spacing.gutter, end = SebaroTheme.tokens.spacing.gutter,
                    top = SebaroTheme.tokens.focus.offset + SebaroTheme.tokens.focus.width), verticalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s3)) {
                    sbChoiceErrorKey(errorKey) {
                        SbCallout(SbCalloutKind.Error, error, Modifier
                            .sbFocusRing(errorInteraction, SebaroTheme.tokens.radius.container)
                            .focusRequester(errorFocus)
                            // CHECKS.md §80 (provisional, agent): focus brought back from below aligns only the sentence, not the ring's room
                            .onFocusChanged { if (it.isFocused) errorScope.launch { scroll.scrollToItem(0) } }
                            .onPreviewKeyEvent { event ->
                                if (event.type != KeyEventType.KeyDown || event.key != Key.DirectionDown) {
                                    false
                                } else if (errorDetails != null && focusManager.moveFocus(FocusDirection.Next)) {
                                    // CHECKS.md §79 (provisional, agent): Down stops at the details, as Tab and Up do
                                    true
                                } else if (firstEnabled >= 0) {
                                    errorScope.launch {
                                        val rowKey = keys[firstEnabled]
                                        if (scroll.layoutInfo.visibleItemsInfo.none { it.key == rowKey }) {
                                            scroll.scrollToItem(firstEnabled + 1)
                                        }
                                        snapshotFlow { scroll.layoutInfo.visibleItemsInfo.any { it.key == rowKey } }.sbFirstVisible { it }
                                        withFrameNanos { }
                                        firstEnabledFocus.requestFocus()
                                    }
                                    true
                                } else false
                            }
                            .focusable(interactionSource = errorInteraction), live = true)
                    }
                    errorDetails?.invoke()
                }
            }
            items(options.size, key = { i -> keys[i] }) { i ->
                val (value, word) = options[i]
                SbRadioRow(word, value == selected,
                    { if (closeOnChoice) onExpandedChange(false); onChange(value) },
                    modifier = Modifier
                        .then(if (i == first) Modifier.focusRequester(focus) else Modifier)
                        .then(if (i == firstEnabled) Modifier.focusRequester(firstEnabledFocus) else Modifier),
                    help = meta[value], enabled = value !in disabledOptions)
                if (i == first) LaunchedEffect(Unit) {
                    if (!requestedFocus) {
                        requestedFocus = true
                        if (error == null) focus.requestFocus()
                    }
                }
            }
            if (extraAction != null) item { extraAction() }
        }
    }
}

